/* Shared material reveal: broad contours, feathered alpha and continuous texture coordinates. */
const surfacePresets={soil:{label:'Earth · fine soil',roughness:9,feather:9,contrast:.8,brightness:.85,scale:1.1,particles:18,color:'#73553b'},snow:{label:'Snow · soft drift',roughness:5,feather:16,contrast:.8,brightness:1,scale:1,particles:28,color:'#e8f2f6'},clouds:{label:'Clouds · mist bank',roughness:19,feather:35,contrast:.8,brightness:1.1,scale:1.2,particles:0,color:'#dce5ed'}};
const surfaceBuffers={};for(const key of ['paint','mask','snow']){const c=document.createElement('canvas');c.width=960;c.height=540;surfaceBuffers[key]=c}
const snowCtx=surfaceBuffers.snow.getContext('2d');snowCtx.fillStyle='#dbe5eb';snowCtx.fillRect(0,0,960,540);for(let i=0;i<16000;i++){const x=(Math.sin(i*91.7)*43758.5)%1,y=(Math.sin(i*37.1)*19341.7)%1;snowCtx.fillStyle=i%3?'#ffffff28':'#8198a21a';snowCtx.fillRect(Math.abs(x)*960,Math.abs(y)*540,1,1)}for(let i=0;i<8;i++){const g=snowCtx.createLinearGradient(0,i*80,0,i*80+90);g.addColorStop(0,'#ffffff00');g.addColorStop(.5,'#ffffff60');g.addColorStop(1,'#8197a030');snowCtx.fillStyle=g;snowCtx.beginPath();snowCtx.ellipse(450,i*80,700,55,-.09,0,Math.PI*2);snowCtx.fill()}
function surfaceSettings(f){const preset=surfacePresets[f.surfaceType]||surfacePresets.soil;return {type:f.surfaceType||'soil',...preset,...f.surfaceSettings}}
function drawSurfaceReveal(ctx,age,duration,f=fx){if(age<0||age>=duration)return;const s=surfaceSettings(f),half=duration/2,first=age<=half,q=motionEase(first?age/half:(age-half)/half,'smooth'),edge=540*(1-q),b=surfaceBuffers.paint,c=b.getContext('2d'),mask=surfaceBuffers.mask,m=mask.getContext('2d');c.clearRect(0,0,960,540);m.clearRect(0,0,960,540);const contour=x=>s.roughness*(.62*Math.sin(x*.009)+.28*Math.sin(x*.026+1.2)+.1*Math.sin(x*.061));m.save();m.filter=`blur(${s.feather}px)`;m.fillStyle='white';m.beginPath();m.moveTo(-80,first?650:-110);for(let x=-80;x<=1040;x+=6)m.lineTo(x,edge+contour(x));m.lineTo(1040,first?650:-110);m.closePath();m.fill();m.restore();c.save();c.filter=`contrast(${s.contrast}) brightness(${s.brightness})`;const source=s.type==='snow'?(ready(sprites.snow)?sprites.snow:surfaceBuffers.snow):s.type==='clouds'?sprites.clouds:sprites.soil;if(source&&(source.width||source.naturalWidth)){const w=960*s.scale,h=600*s.scale;c.drawImage(source,(960-w)/2+Math.sin(age*.16)*3,(540-h)/2,w,h)}else{c.fillStyle=s.color;c.fillRect(0,0,960,540)}c.restore();if(s.type==='clouds'){c.globalCompositeOperation='destination-over';c.fillStyle=s.color;c.fillRect(0,0,960,540);c.globalCompositeOperation='source-over'}c.globalCompositeOperation='destination-in';c.drawImage(mask,0,0);c.globalCompositeOperation='source-over';ctx.drawImage(b,0,0);ctx.save();for(let i=0;i<s.particles;i++){const life=(age*.12+i*.173)%1,x=(i*137.9+age*(f.cityWind||0)*.08+960)%960;ctx.globalAlpha=(1-life)*.22;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(x,edge+contour(x)+life*(s.type==='snow'?-65:30),s.type==='snow'?1.5:1,0,Math.PI*2);ctx.fill()}ctx.restore()}
function surfaceEditor(host,onChange,getState=()=>fx){const f=getState();const box=document.createElement('details');box.innerHTML='<summary>Surface reveal · material & softness</summary><label>Material preset<select id="surfacePreset">'+Object.entries(surfacePresets).map(([k,p])=>`<option value="${k}">${p.label}</option>`).join('')+'</select></label><div id="surfaceFields"></div><p class="sub">Material texture, broad edge shape and feather are independent. Snow uses a natural generated material; clouds use the cloud asset.</p>';host.append(box);const select=box.querySelector('select');select.value=f.surfaceType||'soil';function fields(){const s=surfaceSettings(f),target=box.querySelector('#surfaceFields');target.innerHTML='';for(const [key,label,min,max,step] of [['roughness','Contour height (px)',0,50,1],['feather','Edge feather (px)',0,70,1],['contrast','Texture contrast',.1,1.8,.05],['brightness','Material brightness',.2,1.8,.05],['scale','Texture scale',.5,2,.05],['particles','Particles',0,100,1]]){const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');Object.assign(input,{type:'number',min,max,step,value:s[key]});input.dataset.surface=key;l.append(input);target.append(l);input.oninput=()=>{f.surfaceSettings||={};f.surfaceSettings[key]=Math.max(min,Math.min(max,+input.value));onChange()}}}select.onchange=()=>{f.surfaceType=select.value;f.surfaceSettings={};fields();onChange()};fields();return box}
